const tabId = 1854033397;
const productList = await browserjs(tabId, () => {
  // Find all product cards / tiles
  // Let's inspect links that have product URLs or images
  const cards = Array.from(document.querySelectorAll('.grid-tile, .product-tile, [class*="product-grid"] > div, .product'));

  // Also general approach: find all links inside the product grid container
  const mainGrid = document.querySelector('.product-grid, #product-search-results, [class*="search-results"]');

  // Let's get all product links from main
  const productAnchors = Array.from(document.querySelectorAll('main a'))
    .filter(a => a.href && a.href.includes('.html') && !a.href.includes('cmp=') && a.innerText.trim().length > 3);

  const uniqueProducts = [];
  const seen = new Set();
  for (const a of productAnchors) {
    const text = a.innerText.trim().split('\n')[0];
    if (!seen.has(a.href) && text.length > 5 && !text.startsWith('$')) {
      seen.add(a.href);
      // find surrounding card or parent
      const card = a.closest('.product-tile') || a.closest('.grid-tile') || a.parentElement;
      uniqueProducts.push({
        name: text,
        url: a.href,
        fullText: card ? card.innerText.trim().replace(/\s+/g, ' ') : ''
      });
    }
  }
  return uniqueProducts;
});

