// Let's inspect the cards on https://www.disneystore.com/toys-plush/toys/ with character Stitch sorted by Most Popular
const cards = await browserjs(tabId, () => {
  const tiles = Array.from(document.querySelectorAll('.product-tile, .grid-tile'));
  return tiles.map(t => {
    return {
      title: t.querySelector('.product-tile__product-name, .pdp-link, a')?.innerText?.trim(),
      price: t.querySelector('.price, [class*="price"]')?.innerText?.trim().replace(/\s+/g, ' '),
      rating: t.querySelector('.bv_main_container_row_flex, [class*="rating"]')?.innerText?.trim().replace(/\s+/g, ' '),
      badge: t.querySelector('.badge, [class*="badge"], .product-ribbon')?.innerText?.trim(),
      imageAlt: t.querySelector('img')?.alt
    };
  }).filter(c => c.title);
});
console.log(JSON.stringify(cards.slice(0, 15), null, 2));
