const tabId = 1854033397;
const tileInfo = await browserjs(tabId, () => {
  const firstA = Array.from(document.querySelectorAll('main a')).find(a => a.innerText.includes('Stitch Fluffy Plush'));
  if (!firstA) return 'not found';
  let el = firstA;
  const chain = [];
  for (let i = 0; i < 6; i++) {
    if (el) {
      chain.push({ tag: el.tagName, className: el.className, id: el.id });
      el = el.parentElement;
    }
  }
  return chain;
});
console.log(tileInfo);

