const tabId = 1854033397;
const cards = await browserjs(tabId, () => {
  const tiles = Array.from(document.querySelectorAll('.product'));
  return tiles.map(t => {
    const titleEl = t.querySelector('.product__tile_link, .product__tile_name');
    const priceEl = t.querySelector('.price, [class*="price"]');
    const badgeEl = t.querySelector('.badge, [class*="badge"], .product-ribbon, [class*="ribbon"]');
    const ratingEl = t.querySelector('[class*="rating"], [class*="review"], .bv_main_container_row_flex, .rating__score');
    const img = t.querySelector('img');
    return {
      title: titleEl?.innerText?.trim(),
      price: priceEl?.innerText?.trim().replace(/\s+/g, ' '),
      rating: ratingEl?.innerText?.trim().replace(/\s+/g, ' '),
      badge: badgeEl?.innerText?.trim(),
      alt: img?.alt
    };
  }).filter(c => c.title);
});
console.log("Total tiles:", cards.length);
console.log(JSON.stringify(cards.slice(0, 15), null, 2));

