const tabId = 1854033397;
const allTiles = await browserjs(tabId, () => {
  const tiles = Array.from(document.querySelectorAll('.product'));
  return tiles.map(t => {
    const title = t.querySelector('.product__tile_link, .product__tile_name')?.innerText?.trim();
    const price = t.querySelector('.price, [class*="price"]')?.innerText?.trim().replace(/\s+/g, ' ');
    const rating = t.querySelector('.bv_main_container_row_flex, [class*="rating"]')?.innerText?.trim().replace(/\s+/g, ' ');
    const badge = t.querySelector('.badge, [class*="badge"], .product-ribbon, [class*="ribbon"]')?.innerText?.trim();
    return { title, price, rating, badge };
  });
});
console.log(JSON.stringify(allTiles, null, 2));

